--liquibase formatted sql

--changeset split-core:16
-- users.id must be a REAL identity column, not a bare BIGSERIAL default.
--
-- core/001-initial.sql created it as `id BIGSERIAL PRIMARY KEY`, i.e. only
-- `DEFAULT nextval('users_id_seq')` with is_identity = NO, while
-- com.superhumans.entity.core.User declares @GeneratedValue(strategy = IDENTITY).
-- Hibernate 7 hands ids to such a column from an in-memory block without
-- advancing the sequence, so after any second process (a restart, another JVM,
-- a test context) users_id_seq can lag behind MAX(id). The next nextval() then
-- returns an id that is already taken and UserSeedService aborts the whole
-- application context with `duplicate key value violates unique constraint
-- "users_pkey"` — reproducible on every boot after the first one.
--
-- BY DEFAULT (not ALWAYS) on purpose: data-test-core.sql inserts fixture users
-- with explicit ids, and explicit-id inserts must keep working.
--
-- The sequence name matters. Adding an identity to a column that already has a
-- BIGSERIAL default makes PostgreSQL create a NEW sequence (users_id_seq1) and
-- leave the old one behind — pg_get_serial_sequence() would then keep reporting
-- the stale sequence, so a setval() through it would synchronise the wrong
-- object and the real identity would stay at 1, colliding on its first insert.
-- Therefore the legacy sequence is dropped first, which frees the canonical name
-- for the identity sequence, and the setval() targets that name directly.
ALTER TABLE users ALTER COLUMN id DROP DEFAULT;
ALTER SEQUENCE IF EXISTS users_id_seq OWNED BY NONE;
DROP SEQUENCE IF EXISTS users_id_seq;
ALTER TABLE users ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;

-- Synchronise the identity with existing rows: last_value = MAX(id), is_called
-- = true, so the next insert gets MAX(id)+1 and no existing id can be reissued.
SELECT setval('users_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM users), 0), 1), true);

--rollback guarded: the identity sequence must be at or past MAX(id) before the
--rollback can hand the column back to a bare nextval default.
--rollback DO $$ BEGIN IF (SELECT last_value FROM users_id_seq) < (SELECT COALESCE(MAX(id),0) FROM users) THEN RAISE EXCEPTION 'rollback blocked: users id sequence is below users MAX(id)'; END IF; END $$;
--rollback ALTER TABLE users ALTER COLUMN id DROP IDENTITY IF EXISTS;
--rollback CREATE SEQUENCE IF NOT EXISTS users_id_seq;
--rollback ALTER TABLE users ALTER COLUMN id SET DEFAULT nextval('users_id_seq');
--rollback ALTER SEQUENCE users_id_seq OWNED BY users.id;
--rollback SELECT setval('users_id_seq', GREATEST(COALESCE((SELECT MAX(id) FROM users), 0), 1), true);